+fn profile_finish_to(bottom: f64) -> OpParams {
+    match profile_finish() {
+        OpParams::ProfileFinish { tolerance, clearance_z, top_z, feed, plunge_feed, .. } => OpParams::ProfileFinish {
+            tolerance,
+            clearance_z,
+            top_z,
+            bottom_z: Height::fixed(bottom),
+            feed,
+            plunge_feed,
+        },
+        other => other,
+    }
+}
